7	export default async function AdminBoardPage({ searchParams }: { searchParams: Promise<{ b?: string; app?: string }> }) {
8	  await requireArea("platform");
9	  const sp = await searchParams;
10	
11	  const [apps, allBoards] = await Promise.all([listApps(), listBoards()]);
12	
13	  // Active app filter: an app id, the literal "unassigned", or undefined (all).
14	  const appParam = sp.app;
15	  const activeApp =
16	    appParam === "unassigned" ? "unassigned" : apps.find((a) => a.id === appParam)?.id ?? null;
17	
18	  // Boards visible under the current app filter.
19	  const visibleBoards =
20	    activeApp === "unassigned"
21	      ? allBoards.filter((b) => b.appId === null)
22	      : activeApp
23	        ? allBoards.filter((b) => b.appId === activeApp)
24	        : allBoards;
25	
26	  // Pick the active board: honour ?b= when it's in the visible set, else the
27	  // first visible board.
28	  const activeId = visibleBoards.find((b) => b.id === sp.b)?.id ?? visibleBoards[0]?.id ?? "";
29	  const board = activeId ? await getBoard(activeId) : null;
30	
31	  return (
32	    <BoardClient
33	      apps={apps}
34	      boards={visibleBoards}
35	      board={board}
36	      activeApp={activeApp}
37	      unassignedCount={allBoards.filter((b) => b.appId === null).length}
38	    />
39	  );
40	}
